* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: #f4f4f9;
    color: #333;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background: #ffffff;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    text-align: center;
    max-width: 400px;
    width: 100%;
}

h1 {
    margin-bottom: 1rem;
    color: #2c3e50;
}

p {
    margin-bottom: 1.5rem;
    color: #666;
}

.btn {
    background-color: #3498db;
    color: white;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.2s ease;
}

.btn:hover {
    background-color: #2980b9;
}

.output {
    margin-top: 1.5rem;
    font-size: 1.1rem;
    font-weight: 500;
    color: #27ae60;
}

document.addEventListener('DOMContentLoaded', () => {
    const button = document.getElementById('action-btn');
    const output = document.getElementById('output');

    let clickCount = 0;

    button.addEventListener('click', () => {
        clickCount++;
        output.textContent = `Button clicked ${clickCount} time${clickCount === 1 ? '' : 's'}!`;
    });
});

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    user-select: none;
}

body {
    background-color: #05050a;
    color: #00ffff;
    font-family: 'Share Tech Mono', monospace;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    overflow: hidden;
    background-image: 
        radial-gradient(circle at 50% 30%, #110022 0%, #05050a 70%),
        linear-gradient(rgba(0, 255, 255, 0.03) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 255, 255, 0.03) 1px, transparent 1px);
    background-size: 100% 100%, 40px 40px, 40px 40px;
}

#game-container {
    position: relative;
    width: 800px;
    height: 450px;
    background: #080812;
    border: 3px solid #ff00ff;
    box-shadow: 0 0 25px rgba(255, 0, 255, 0.5), inset 0 0 20px rgba(0, 255, 255, 0.2);
    border-radius: 8px;
    overflow: hidden;
}

#hud {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 50px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 20px;
    background: linear-gradient(to bottom, rgba(5,5,10,0.9), rgba(5,5,10,0));
    z-index: 10;
    font-family: 'Press Start 2P', monospace;
    font-size: 12px;
}

.hud-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.label {
    font-size: 8px;
    color: #ff00ff;
    margin-bottom: 4px;
    letter-spacing: 1px;
}

.value {
    color: #00ffff;
    text-shadow: 0 0 8px rgba(0, 255, 255, 0.8);
}

.energy-bar-container {
    width: 120px;
    height: 10px;
    background: #111;
    border: 2px solid #00ffff;
    border-radius: 3px;
    overflow: hidden;
    position: relative;
    box-shadow: 0 0 5px rgba(0, 255, 255, 0.5);
}

#energy-bar {
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, #00ffff, #ff00ff);
    transition: width 0.1s linear;
}

canvas {
    display: block;
    background: #050510;
}

.overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(5, 5, 12, 0.88);
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 20;
    backdrop-filter: blur(4px);
    transition: opacity 0.3s ease;
}

.overlay.hidden {
    opacity: 0;
    pointer-events: none;
    display: none;
}

.title-glow {
    font-family: 'Press Start 2P', monospace;
    font-size: 32px;
    color: #00ffff;
    text-shadow: 0 0 10px #00ffff, 0 0 20px #00ffff, 0 0 30px #ff00ff;
    margin-bottom: 5px;
    text-align: center;
    animation: pulseGlow 2s infinite alternate;
}

.game-over-text {
    color: #ff0055;
    text-shadow: 0 0 10px #ff0055, 0 0 20px #ff0055, 0 0 30px #ff0000;
}

.subtitle {
    font-family: 'Press Start 2P', monospace;
    font-size: 10px;
    color: #ff00ff;
    letter-spacing: 3px;
    margin-bottom: 30px;
}

.instructions-box {
    background: rgba(0, 255, 255, 0.05);
    border: 1px dashed rgba(0, 255, 255, 0.4);
    padding: 15px 25px;
    border-radius: 5px;
    margin-bottom: 25px;
    text-align: center;
    line-height: 1.8;
    font-size: 14px;
}

.key {
    background: #111;
    border: 1px solid #00ffff;
    padding: 2px 6px;
    border-radius: 3px;
    color: #00ffff;
    font-weight: bold;
    box-shadow: 0 0 5px rgba(0, 255, 255, 0.3);
}

.stats-box {
    font-family: 'Press Start 2P', monospace;
    font-size: 12px;
    text-align: center;
    line-height: 2;
    margin-bottom: 25px;
    color: #00ffff;
}

.arcade-btn {
    font-family: 'Press Start 2P', monospace;
    font-size: 14px;
    background: transparent;
    color: #00ffff;
    border: 2px solid #00ffff;
    padding: 12px 24px;
    cursor: pointer;
    border-radius: 4px;
    box-shadow: 0 0 15px rgba(0, 255, 255, 0.4);
    transition: all 0.2s ease;
    text-transform: uppercase;
}

.arcade-btn:hover {
    background: #00ffff;
    color: #05050a;
    box-shadow: 0 0 25px #00ffff, 0 0 50px #ff00ff;
    transform: scale(1.05);
}

.arcade-btn:active {
    transform: scale(0.95);
}

#mobile-controls {
    display: none;
    position: absolute;
    bottom: 15px;
    left: 0;
    width: 100%;
    justify-content: space-around;
    padding: 0 20px;
    z-index: 15;
}

.mob-btn {
    font-family: 'Press Start 2P', monospace;
    font-size: 10px;
    background: rgba(0, 255, 255, 0.1);
    color: #00ffff;
    border: 2px solid #00ffff;
    padding: 12px 18px;
    border-radius: 50px;
    box-shadow: 0 0 10px rgba(0, 255, 255, 0.3);
}

.mob-btn:active {
    background: #00ffff;
    color: #000;
}

@keyframes pulseGlow {
    0% {
        text-shadow: 0 0 10px #00ffff, 0 0 20px #00ffff, 0 0 30px #ff00ff;
    }
    100% {
        text-shadow: 0 0 15px #00ffff, 0 0 25px #ff00ff, 0 0 40px #ff00ff;
    }
}

@media(max-width: 850px) {
    #game-container {
        width: 100vw;
        height: 100vh;
        border: none;
        border-radius: 0;
    }
    canvas {
        width: 100vw;
        height: calc(100vh - 50px);
    }
    #mobile-controls {
        display: flex;
    }
}

// ==========================================
// CYBER DASH - NEON RUNNER 2077
// ==========================================

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// DOM Elements
const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');
const energyBar = document.getElementById('energy-bar');
const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');
const finalScoreEl = document.getElementById('final-score');
const finalDistanceEl = document.getElementById('final-distance');

// Mobile Controls
const btnJump = document.getElementById('btn-jump');
const btnSlide = document.getElementById('btn-slide');
const btnPulse = document.getElementById('btn-pulse');

// Game States
const STATE = {
    START: 0,
    PLAYING: 1,
    GAMEOVER: 2
};
let gameState = STATE.START;

// Game Variables
let score = 0;
let highScore = localStorage.getItem('cyberDashHighScore') || 0;
let distance = 0;
let gameSpeed = 6;
let baseSpeed = 6;
let gravity = 0.6;
let groundY = 370;

highScoreEl.textContent = String(highScore).padStart(6, '0');

// Input tracking
const keys = {};

// Background Elements (Parallax layers)
let stars = [];
let gridLines = [];
let buildingsFar = [];
let buildingsNear = [];
let particles = [];
let floatingTexts = [];
let shockwaves = [];

// Player Object
const player = {
    x: 100,
    y: groundY,
    width: 36,
    height: 52,
    vy: 0,
    jumpPower: -12.5,
    jumps: 0,
    maxJumps: 2,
    isSliding: false,
    slideTimer: 0,
    slideDuration: 30, // frames
    normalHeight: 52,
    slideHeight: 28,
    color: '#00ffff',
    glowColor: 'rgba(0, 255, 255, 0.8)',
    energy: 100,
    maxEnergy: 100,
    isInvincible: false,
    invincibleTimer: 0,
    trail: []
};

// Entities
let obstacles = [];
let collectibles = [];
let spawnTimer = 0;
let spawnInterval = 90; // frames

// Initialize Parallax Environments
function initEnvironment() {
    stars = [];
    for (let i = 0; i < 60; i++) {
        stars.push({
            x: Math.random() * canvas.width,
            y: Math.random() * (groundY - 50),
            size: Math.random() * 2,
            speed: 0.2 + Math.random() * 0.5
        });
    }

    buildingsFar = [];
    let xFar = 0;
    while (xFar < canvas.width + 200) {
        let w = 60 + Math.random() * 80;
        let h = 100 + Math.random() * 120;
        buildingsFar.push({ x: xFar, width: w, height: h, color: '#120a2a' });
        xFar += w + 10;
    }

    buildingsNear = [];
    let xNear = 0;
    while (xNear < canvas.width + 200) {
        let w = 40 + Math.random() * 60;
        let h = 60 + Math.random() * 90;
        buildingsNear.push({ 
            x: xNear, 
            width: w, 
            height: h, 
            color: '#1a0b36',
            windows: Math.random() > 0.5 
        });
        xNear += w + 20;
    }

    gridLines = [];
    for (let i = 0; i < 20; i++) {
        gridLines.push(i * 50);
    }
}

// Reset Game State
function resetGame() {
    score = 0;
    distance = 0;
    gameSpeed = baseSpeed;
    obstacles = [];
    collectibles = [];
    particles = [];
    floatingTexts = [];
    shockwaves = [];
    spawnTimer = 0;
    spawnInterval = 90;
    player.y = groundY - player.height;
    player.vy = 0;
    player.jumps = 0;
    player.isSliding = false;
    player.energy = 100;
    player.height = player.normalHeight;
    player.isInvincible = false;
    player.invincibleTimer = 0;
    player.trail = [];
    initEnvironment();
}

// Event Listeners
window.addEventListener('keydown', e => {
    if (['Space', 'ArrowUp', 'ArrowDown', 'KeyE'].includes(e.code)) {
        e.preventDefault(); // Prevent page scroll
    }
    keys[e.code] = true;

    if (gameState === STATE.PLAYING) {
        if ((e.code === 'Space' || e.code === 'ArrowUp') && !player.isSliding) {
            jump();
        }
        if (e.code === 'ArrowDown') {
            slide(true);
        }
        if (e.code === 'KeyE') {
            triggerPulse();
        }
    } else if (gameState === STATE.START && (e.code === 'Space' || e.code === 'Enter')) {
        startGame();
    } else if (gameState === STATE.GAMEOVER && (e.code === 'Space' || e.code === 'Enter')) {
        startGame();
    }
});

window.addEventListener('keyup', e => {
    keys[e.code] = false;
    if (e.code === 'ArrowDown') {
        slide(false);
    }
});

// Mobile button listeners
btnJump.addEventListener('touchstart', (e) => { e.preventDefault(); if(gameState === STATE.PLAYING) jump(); });
btnSlide.addEventListener('touchstart', (e) => { e.preventDefault(); if(gameState === STATE.PLAYING) slide(true); });
btnSlide.addEventListener('touchend', (e) => { e.preventDefault(); if(gameState === STATE.PLAYING) slide(false); });
btnPulse.addEventListener('touchstart', (e) => { e.preventDefault(); if(gameState === STATE.PLAYING) triggerPulse(); });

startBtn.addEventListener('click', startGame);
restartBtn.addEventListener('click', startGame);

function startGame() {
    resetGame();
    gameState = STATE.PLAYING;
    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
}

function gameOver() {
    gameState = STATE.GAMEOVER;
    finalScoreEl.textContent = Math.floor(score);
    finalDistanceEl.textContent = Math.floor(distance);
    if (score > highScore) {
        highScore = Math.floor(score);
        localStorage.setItem('cyberDashHighScore', highScore);
        highScoreEl.textContent = String(highScore).padStart(6, '0');
    }
    gameOverScreen.classList.remove('hidden');
}

// Player Actions
function jump() {
    if (player.jumps < player.maxJumps) {
        if (player.isSliding) {
            player.isSliding = false;
            player.height = player.normalHeight;
            player.y = groundY - player.height;
        }
        player.vy = player.jumpPower;
        player.jumps++;

        // Create jump particles
        createParticles(player.x + player.width/2, player.y + player.height, 12, '#00ffff');

        // Second jump extra boost & effect
        if (player.jumps === 2) {
            player.vy = player.jumpPower * 0.9;
            createShockwave(player.x + player.width/2, player.y + player.height/2, '#ff00ff');
            addFloatingText("DOUBLE JUMP!", player.x, player.y - 20, '#ff00ff');
        }
    }
}

function slide(activate) {
    if (activate && player.jumps === 0) {
        if (!player.isSliding) {
            player.isSliding = true;
            player.height = player.slideHeight;
            player.y = groundY - player.height;
            createParticles(player.x + player.width/2, groundY, 8, '#ff0055');
        }
    } else if (!activate && player.isSliding) {
        player.isSliding = false;
        player.height = player.normalHeight;
        player.y = groundY - player.height;
    }
}

function triggerPulse() {
    if (player.energy >= 35) {
        player.energy -= 35;
        createShockwave(player.x + player.width/2, player.y + player.height/2, '#00ffff');
        addFloatingText("PULSE BLAST!", player.x, player.y - 30, '#00ffff');

        // Destroy obstacles in proximity
        obstacles.forEach(obs => {
            let dist = Math.hypot((obs.x + obs.width/2) - (player.x + player.width/2), (obs.y + obs.height/2) - (player.y + player.height/2));
            if (dist < 220) {
                obs.destroyed = true;
                createParticles(obs.x + obs.width/2, obs.y + obs.height/2, 20, '#00ffff');
                score += 150;
            }
        });
        obstacles = obstacles.filter(obs => !obs.destroyed);

        // Collect items in proximity
        collectibles.forEach(item => {
            item.collected = true;
            player.energy = Math.min(player.maxEnergy, player.energy + 25);
            score += 100;
            createParticles(item.x, item.y, 10, '#ffff00');
        });
        collectibles = collectibles.filter(item => !item.collected);
    }
}

// Particle & Effect Generators
function createParticles(x, y, count, color) {
    for (let i = 0; i < count; i++) {
        particles.push({
            x: x,
            y: y,
            vx: (Math.random() - 0.5) * 8,
            vy: (Math.random() - 0.5) * 8,
            size: 2 + Math.random() * 3,
            color: color,
            alpha: 1,
            decay: 0.03 + Math.random() * 0.04
        });
    }
}

function createShockwave(x, y, color) {
    shockwaves.push({
        x: x,
        y: y,
        radius: 10,
        maxRadius: 180,
        color: color,
        alpha: 1
    });
}

function addFloatingText(text, x, y, color) {
    floatingTexts.push({
        text: text,
        x: x,
        y: y,
        vy: -1.5,
        alpha: 1,
        color: color
    });
}

// Spawner logic
function spawnEntity() {
    let rand = Math.random();

    if (rand < 0.65) {
        // Obstacles
        let obsType = Math.random();
        if (obsType < 0.4) {
            // Ground drone / barrier
            obstacles.push({
                type: 'ground',
                x: canvas.width + 50,
                y: groundY - 40,
                width: 32,
                height: 40,
                color: '#ff0055'
            });
        } else if (obsType < 0.75) {
            // Flying drone (requires slide or low jump)
            obstacles.push({
                type: 'flying',
                x: canvas.width + 50,
                y: groundY - 95,
                width: 40,
                height: 24,
                color: '#ffaa00',
                oscillation: Math.random() * Math.PI
            });
        } else {
            // Tall laser barrier
            obstacles.push({
                type: 'laser',
                x: canvas.width + 50,
                y: groundY - 110,
                width: 16,
                height: 110,
                color: '#ff00ff'
            });
        }
    } else {
        // Collectible Energy Node
        collectibles.push({
            x: canvas.width + 50,
            y: groundY - (Math.random() > 0.5 ? 60 : 130),
            radius: 12,
            bobOffset: Math.random() * Math.PI
        });
    }
}

// Update Loop
function update(dt) {
    if (gameState !== STATE.PLAYING) return;

    // Increase game speed & distance
    gameSpeed += 0.001;
    distance += gameSpeed * 0.1;
    score += gameSpeed * 0.2;

    // Passive energy regeneration / drain
    player.energy = Math.min(player.maxEnergy, player.energy + 0.05);

    // Update Player physics
    player.vy += gravity;
    player.y += player.vy;

    // Ground collision
    if (player.y >= groundY - player.height) {
        player.y = groundY - player.height;
        player.vy = 0;
        player.jumps = 0;
    }

    // Sliding timer
    if (player.isSliding) {
        player.slideTimer++;
        if (player.slideTimer > player.slideDuration) {
            // Check if ceiling is clear before standing up
            player.isSliding = false;
            player.height = player.normalHeight;
            player.y = groundY - player.height;
            player.slideTimer = 0;
        }
    }

    // Player trail effect
    if (Math.random() < 0.5) {
        player.trail.push({
            x: player.x,
            y: player.y,
            width: player.width,
            height: player.height,
            alpha: 0.4
        });
        if (player.trail.length > 8) player.trail.shift();
    }
    player.trail.forEach(t => t.alpha -= 0.05);

    // Invincibility timer
    if (player.isInvincible) {
        player.invincibleTimer--;
        if (player.invincibleTimer <= 0) player.isInvincible = false;
    }

    // Spawner timer
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
        spawnEntity();
        spawnTimer = 0;
        // Gradually decrease spawn interval for higher difficulty
        spawnInterval = Math.max(50, 90 - Math.floor(distance / 150));
    }

    // Update Obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        if (obs.type === 'flying') {
            obs.oscillation += 0.1;
            obs.y += Math.sin(obs.oscillation) * 1.5;
        }

        // Collision Check (AABB with slight padding for fairness)
        let pad = 6;
        if (
            player.x + pad < obs.x + obs.width - pad &&
            player.x + player.width - pad > obs.x + pad &&
            player.y + pad < obs.y + obs.height - pad &&
            player.y + player.height - pad > obs.y + pad
        ) {
            if (!player.isInvincible) {
                createParticles(player.x + player.width/2, player.y + player.height/2, 25, '#ff0055');
                gameOver();
                return;
            }
        }

        // Remove offscreen obstacles
        if (obs.x + obs.width < -50) {
            obstacles.splice(i, 1);
            score += 25;
        }
    }

    // Update Collectibles
    for (let i = collectibles.length - 1; i >= 0; i--) {
        let item = collectibles[i];
        item.x -= gameSpeed;
        item.bobOffset += 0.08;
        let currentY = item.y + Math.sin(item.bobOffset) * 6;

        // Player collision with collectible
        let dist = Math.hypot((player.x + player.width/2) - item.x, (player.y + player.height/2) - currentY);
        if (dist < player.width/2 + item.radius) {
            player.energy = Math.min(player.maxEnergy, player.energy + 30);
            score += 150;
            addFloatingText("+ENERGY", item.x, item.y - 15, '#00ffff');
            createParticles(item.x, currentY, 12, '#ffff00');
            collectibles.splice(i, 1);
            continue;
        }

        if (item.x < -50) {
            collectibles.splice(i, 1);
        }
    }

    // Update Particles
    particles.forEach(p => {
        p.x += p.vx;
        p.y += p.vy;
        p.alpha -= p.decay;
    });
    particles = particles.filter(p => p.alpha > 0);

    // Update Shockwaves
    shockwaves.forEach(sw => {
        sw.radius += 6;
        sw.alpha -= 0.04;
    });
    shockwaves = shockwaves.filter(sw => sw.alpha > 0);

    // Update Floating Texts
    floatingTexts.forEach(ft => {
        ft.y += ft.vy;
        ft.alpha -= 0.02;
    });
    floatingTexts = floatingTexts.filter(ft => ft.alpha > 0);

    // Update Parallax & Grid
    stars.forEach(s => {
        s.x -= s.speed;
        if (s.x < 0) s.x = canvas.width;
    });

    buildingsFar.forEach(b => {
        b.x -= gameSpeed * 0.2;
        if (b.x + b.width < 0) {
            b.x = canvas.width + Math.random() * 50;
            b.width = 60 + Math.random() * 80;
            b.height = 100 + Math.random() * 120;
        }
    });

    buildingsNear.forEach(b => {
        b.x -= gameSpeed * 0.5;
        if (b.x + b.width < 0) {
            b.x = canvas.width + Math.random() * 80;
            b.width = 40 + Math.random() * 60;
            b.height = 60 + Math.random() * 90;
        }
    });

    gridLines.forEach((gl, idx) => {
        gridLines[idx] -= gameSpeed;
        if (gridLines[idx] < 0) {
            gridLines[idx] = canvas.width;
        }
    });

    // HUD update
    scoreEl.textContent = String(Math.floor(score)).padStart(6, '0');
    energyBar.style.width = `${(player.energy / player.maxEnergy) * 100}%`;
}

// Render Loop
function render() {
    // Clear canvas
    ctx.fillStyle = '#050510';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Render Stars
    ctx.fillStyle = '#ffffff';
    stars.forEach(s => {
        ctx.globalAlpha = 0.6;
        ctx.fillRect(s.x, s.y, s.size, s.size);
    });
    ctx.globalAlpha = 1;

    // Render Far Buildings (Silhouette)
    ctx.fillStyle = '#0d071a';
    buildingsFar.forEach(b => {
        ctx.fillRect(b.x, groundY - b.height, b.width, b.height);
    });

    // Render Near Buildings with Neon Windows
    buildingsNear.forEach(b => {
        ctx.fillStyle = '#140b2b';
        ctx.fillRect(b.x, groundY - b.height, b.width, b.height);

        // Neon top edge accent
        ctx.strokeStyle = '#ff00ff22';
        ctx.lineWidth = 2;
        ctx.strokeRect(b.x, groundY - b.height, b.width, b.height);

        // Windows
        if (b.windows) {
            ctx.fillStyle = 'rgba(0, 255, 255, 0.15)';
            for (let wx = b.x + 8; wx < b.x + b.width - 10; wx += 14) {
                for (let wy = groundY - b.height + 10; wy < groundY - 20; wy += 20) {
                    ctx.fillRect(wx, wy, 6, 10);
                }
            }
        }
    });

    // Render Horizon Neon Glow Line
    ctx.strokeStyle = '#ff00ff';
    ctx.shadowColor = '#ff00ff';
    ctx.shadowBlur = 12;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, groundY);
    ctx.lineTo(canvas.width, groundY);
    ctx.stroke();
    ctx.shadowBlur = 0; // reset

    // Render Perspective Cyber Ground Grid Lines (Moving vertical markers)
    ctx.strokeStyle = 'rgba(0, 255, 255, 0.25)';
    ctx.lineWidth = 1;
    gridLines.forEach(gl => {
        ctx.beginPath();
        ctx.moveTo(gl, groundY);
        ctx.lineTo(gl + (gl - canvas.width/2) * 0.6, canvas.height);
        ctx.stroke();
    });

    // Render Ground Fill
    ctx.fillStyle = '#05050f';
    ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);

    // Render Player Trail
    player.trail.forEach(t => {
        ctx.fillStyle = player.color;
        ctx.globalAlpha = t.alpha;
        ctx.fillRect(t.x, t.y, t.width, t.height);
    });
    ctx.globalAlpha = 1;

    // Render Player (Cyber Runner Avatar with Visor & Neon Glow)
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 15;
    ctx.fillStyle = '#080816';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.strokeStyle = player.color;
    ctx.lineWidth = 2;
    ctx.strokeRect(player.x, player.y, player.width, player.height);

    // Player Visor / Cyber details
    if (!player.isSliding) {
        // Visor glowing eye
        ctx.fillStyle = '#ff00ff';
        ctx.fillRect(player.x + 18, player.y + 10, 14, 6);
        // Jacket neon stripes
        ctx.fillStyle = '#00ffff';
        ctx.fillRect(player.x + 6, player.y + 22, 24, 4);
    } else {
        // Slide posture visor
        ctx.fillStyle = '#ff00ff';
        ctx.fillRect(player.x + 16, player.y + 6, 14, 4);
    }
    ctx.shadowBlur = 0; // reset

    // Render Obstacles
    obstacles.forEach(obs => {
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 12;
        ctx.fillStyle = '#110515';
        ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

        ctx.strokeStyle = obs.color;
        ctx.lineWidth = 2;
        ctx.strokeRect(obs.x, obs.y, obs.width, obs.height);

        // Internal details per obstacle type
        if (obs.type === 'drone' || obs.type === 'flying') {
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(obs.x + 8, obs.y + 8, obs.width - 16, 4);
        } else if (obs.type === 'laser') {
            ctx.fillStyle = 'rgba(255, 0, 255, 0.4)';
            ctx.fillRect(obs.x + 4, obs.y, 8, obs.height);
        }
        ctx.shadowBlur = 0;
    });

    // Render Collectibles (Energy Nodes)
    collectibles.forEach(item => {
        let currentY = item.y + Math.sin(item.bobOffset) * 6;
        ctx.shadowColor = '#ffff00';
        ctx.shadowBlur = 15;

        ctx.fillStyle = '#ffff00';
        ctx.beginPath();
        ctx.arc(item.x, currentY, item.radius, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#050510';
        ctx.beginPath();
        ctx.arc(item.x, currentY, item.radius - 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.shadowBlur = 0;
    });

    // Render Shockwaves
    shockwaves.forEach(sw => {
        ctx.strokeStyle = sw.color;
        ctx.globalAlpha = sw.alpha;
        ctx.lineWidth = 3;
        ctx.shadowColor = sw.color;
        ctx.shadowBlur = 15;
        ctx.beginPath();
        ctx.arc(sw.x, sw.y, sw.radius, 0, Math.PI * 2);
        ctx.stroke();
        ctx.shadowBlur = 0;
    });
    ctx.globalAlpha = 1;

    // Render Particles
    particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 8;
        ctx.fillRect(p.x, p.y, p.size, p.size);
    });
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;

    // Render Floating Texts
    floatingTexts.forEach(ft => {
        ctx.font = '10px "Press Start 2P"';
        ctx.fillStyle = ft.color;
        ctx.globalAlpha = ft.alpha;
        ctx.shadowColor = ft.color;
        ctx.shadowBlur = 10;
        ctx.fillText(ft.text, ft.x - 20, ft.y);
    });
    ctx.globalAlpha = 1;
    ctx.shadowBlur = 0;
}

// Game Loop
let lastTime = 0;
function gameLoop(timestamp) {
    let dt = timestamp - lastTime;
    lastTime = timestamp;

    update(dt);
    render();

    requestAnimationFrame(gameLoop);
}

// Initial setup
initEnvironment();
render();
requestAnimationFrame(gameLoop);

