const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');
const finalScoreEl = document.getElementById('final-score');
const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');

let score = 0;
let highScore = localStorage.getItem('neon_runner_highscore') || 0;
highScoreEl.textContent = highScore;

let gameState = 'START'; // START, PLAYING, GAMEOVER

// Game configuration & objects
let gameSpeed = 5;
let gravity = 0.6;

const player = {
  x: 80,
  y: 280,
  width: 40,
  height: 50,
  vy: 0,
  jumpStrength: -11,
  doubleJumpStrength: -9.5,
  jumps: 0,
  maxJumps: 2,
  grounded: false,
  color: '#00f3ff',
  trail: []
};

let obstacles = [];
let particles = [];
let stars = [];
let groundX = 0;

// Initialize background stars
for (let i = 0; i < 50; i++) {
  stars.push({
    x: Math.random() * canvas.width,
    y: Math.random() * (canvas.height - 80),
    size: Math.random() * 2 + 1,
    speed: Math.random() * 0.5 + 0.2
  });
}

function spawnObstacle() {
  const types = ['spike', 'tall', 'floating'];
  const type = types[Math.floor(Math.random() * types.length)];

  let obs = {
    x: canvas.width + 50,
    width: 30,
    height: 40,
    y: 330 - 40,
    color: '#ff007f',
    type: type
  };

  if (type === 'tall') {
    obs.width = 35;
    obs.height = 70;
    obs.y = 330 - 70;
    obs.color = '#ffaa00';
  } else if (type === 'floating') {
    obs.width = 40;
    obs.height = 30;
    obs.y = 230; // floating above player jump height range
    obs.color = '#bf00ff';
  }

  obstacles.push(obs);
}

let spawnTimer = 0;
let spawnInterval = 100;

function jump() {
  if (gameState !== 'PLAYING') return;

  if (player.grounded) {
    player.vy = player.jumpStrength;
    player.grounded = false;
    player.jumps = 1;
    createJumpParticles(player.x + player.width / 2, player.y + player.height);
  } else if (player.jumps < player.maxJumps) {
    player.vy = player.doubleJumpStrength;
    player.jumps++;
    createJumpParticles(player.x + player.width / 2, player.y + player.height, '#ff007f');
  }
}

function createJumpParticles(x, y, color = '#00f3ff') {
  for (let i = 0; i < 12; i++) {
    particles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6 - 2,
      radius: Math.random() * 3 + 1,
      color: color,
      alpha: 1,
      decay: Math.random() * 0.03 + 0.02
    });
  }
}

function createExplosion(x, y) {
  for (let i = 0; i < 40; i++) {
    particles.push({
      x: x,
      y: y,
      vx: (Math.random() - 0.5) * 10,
      vy: (Math.random() - 0.5) * 10,
      radius: Math.random() * 4 + 2,
      color: Math.random() > 0.5 ? '#ff007f' : '#00f3ff',
      alpha: 1,
      decay: Math.random() * 0.02 + 0.01
    });
  }
}

// Input listeners
window.addEventListener('keydown', (e) => {
  if (['Space', 'ArrowUp', 'KeyW'].includes(e.code)) {
    e.preventDefault();
    if (gameState === 'PLAYING') {
      jump();
    } else if (gameState === 'START') {
      startGame();
    } else if (gameState === 'GAMEOVER') {
      resetGame();
    }
  }
});

canvas.addEventListener('click', () => {
  if (gameState === 'PLAYING') {
    jump();
  }
});

startBtn.addEventListener('click', startGame);
restartBtn.addEventListener('click', resetGame);

function startGame() {
  gameState = 'PLAYING';
  startScreen.classList.add('hidden');
  score = 0;
  gameSpeed = 5;
  obstacles = [];
  particles = [];
  spawnTimer = 0;
  player.y = 280;
  player.vy = 0;
  player.jumps = 0;
  player.grounded = true;
}

function resetGame() {
  gameState = 'PLAYING';
  gameOverScreen.classList.add('hidden');
  score = 0;
  gameSpeed = 5;
  obstacles = [];
  particles = [];
  spawnTimer = 0;
  player.y = 280;
  player.vy = 0;
  player.jumps = 0;
  player.grounded = true;
}

function gameOver() {
  gameState = 'GAMEOVER';
  createExplosion(player.x + player.width / 2, player.y + player.height / 2);
  finalScoreEl.textContent = Math.floor(score);
  if (score > highScore) {
    highScore = Math.floor(score);
    localStorage.setItem('neon_runner_highscore', highScore);
    highScoreEl.textContent = highScore;
  }
  setTimeout(() => {
    gameOverScreen.classList.remove('hidden');
  }, 400);
}

function update() {
  if (gameState !== 'PLAYING') return;

  // Score & speed progression
  score += 0.1;
  scoreEl.textContent = Math.floor(score);
  gameSpeed = 5 + Math.floor(score / 100) * 0.5;

  // Player physics
  player.vy += gravity;
  player.y += player.vy;

  // Ground collision
  const floorY = 330 - player.height;
  if (player.y >= floorY) {
    player.y = floorY;
    player.vy = 0;
    player.grounded = true;
    player.jumps = 0;
  }

  // Player trail effect
  player.trail.push({ x: player.x, y: player.y });
  if (player.trail.length > 5) {
    player.trail.shift();
  }

  // Ground movement
  groundX = (groundX + gameSpeed) % 40;

  // Stars parallax
  stars.forEach(star => {
    star.x -= star.speed;
    if (star.x < 0) star.x = canvas.width;
  });

  // Obstacle spawning
  spawnTimer++;
  if (spawnTimer >= Math.max(50, spawnInterval - Math.floor(score / 50) * 5)) {
    spawnObstacle();
    spawnTimer = 0;
    spawnInterval = Math.floor(Math.random() * 40) + 80;
  }

  // Update obstacles
  for (let i = obstacles.length - 1; i >= 0; i--) {
    let obs = obstacles[i];
    obs.x -= gameSpeed;

    // AABB Collision Detection with slight padding for fairness
    const padding = 6;
    if (
      player.x + padding < obs.x + obs.width - padding &&
      player.x + player.width - padding > obs.x + padding &&
      player.y + padding < obs.y + obs.height - padding &&
      player.y + player.height - padding > obs.y + padding
    ) {
      gameOver();
    }

    // Remove off-screen obstacles
    if (obs.x + obs.width < 0) {
      obstacles.splice(i, 1);
    }
  }

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.alpha -= p.decay;
    if (p.alpha <= 0) {
      particles.splice(i, 1);
    }
  }
}

function draw() {
  // Clear canvas
  ctx.fillStyle = '#0a0a16';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw background stars
  ctx.fillStyle = '#ffffff';
  stars.forEach(star => {
    ctx.globalAlpha = Math.random() * 0.5 + 0.5;
    ctx.fillRect(star.x, star.y, star.size, star.size);
  });
  ctx.globalAlpha = 1;

  // Draw grid lines in background for synthwave neon vibe
  ctx.strokeStyle = 'rgba(0, 243, 255, 0.05)';
  ctx.lineWidth = 1;
  for (let x = 0; x < canvas.width; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 330);
    ctx.stroke();
  }

  // Draw Ground
  ctx.fillStyle = '#12122b';
  ctx.fillRect(0, 330, canvas.width, canvas.height - 330);

  // Neon Ground Top Line
  ctx.strokeStyle = '#00f3ff';
  ctx.shadowColor = '#00f3ff';
  ctx.shadowBlur = 10;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, 330);
  ctx.lineTo(canvas.width, 330);
  ctx.stroke();

  // Ground dash marks
  ctx.strokeStyle = '#ff007f';
  ctx.shadowColor = '#ff007f';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let x = -groundX; x < canvas.width; x += 40) {
    ctx.moveTo(x, 345);
    ctx.lineTo(x + 20, 345);
  }
  ctx.stroke();
  ctx.shadowBlur = 0; // reset shadow

  // Draw Player Trail
  player.trail.forEach((pos, index) => {
    const alpha = (index + 1) / player.trail.length * 0.3;
    ctx.fillStyle = player.color;
    ctx.globalAlpha = alpha;
    ctx.fillRect(pos.x, pos.y, player.width, player.height);
  });
  ctx.globalAlpha = 1;

  // Draw Player
  ctx.shadowColor = player.color;
  ctx.shadowBlur = 15;
  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Player visor / inner detail
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(player.x + 20, player.y + 10, 14, 8);
  ctx.shadowBlur = 0;

  // Draw Obstacles
  obstacles.forEach(obs => {
    ctx.shadowColor = obs.color;
    ctx.shadowBlur = 15;
    ctx.fillStyle = obs.color;
    ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

    // Inner glow core
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(obs.x + 4, obs.y + 4, obs.width - 8, 4);
    ctx.shadowBlur = 0;
  });

  // Draw Particles
  particles.forEach(p => {
    ctx.save();
    ctx.globalAlpha = p.alpha;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 8;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();

